24	use Doctrine\Common\Collections\ArrayCollection;
25	use Doctrine\Common\Collections\Collection;
26	use Doctrine\ORM\Mapping as ORM;
27	
28	#[ORM\Entity]
29	#[ORM\Table(name: 'orders')]
30	final class Order extends AggregateRoot
31	{
32	    /** @var Collection<int, OrderItem> */
33	    #[ORM\OneToMany(targetEntity: OrderItem::class, mappedBy: 'order', cascade: ['persist'], orphanRemoval: true)]
34	    private Collection $lines;
35	
36	    /**
37	     * Položky jen ke čtení: vrací se kopie, přidává se přes addItem().
38	     *
39	     * @var list<OrderItem>
40	     */
41	    public array $items {
42	        get => array_values($this->lines->toArray());
43	    }
44	
45	    // Asymetrická viditelnost: přečte kdokoli, zapíše jen kód uvnitř třídy.
46	    #[ORM\Column(enumType: OrderStatus::class)]
47	    public private(set) OrderStatus $status;
48	
49	    #[ORM\Column(nullable: true)]
50	    public private(set) ?\DateTimeImmutable $placedAt = null;
51	
52	    // Sleva na celou objednávku. Kniha ji nemá, kurz ano (viz README).
53	    #[ORM\Embedded(class: Money::class, columnPrefix: 'discount_')]
54	    public private(set) Money $discount;
55	
56	    private function __construct(
57	        #[ORM\Id]
58	        #[ORM\Column(type: 'order_id')]
59	        public readonly OrderId $id,
60	        #[ORM\Column(type: 'customer_id')]
61	        public readonly CustomerId $customerId,
62	        #[ORM\Column(enumType: Currency::class)]
63	        public readonly Currency $currency,
64	    ) {
65	        $this->status = OrderStatus::Draft;
66	        $this->lines = new ArrayCollection();
67	        $this->discount = Money::zero($currency);
68	    }
69	
70	    public static function place(OrderId $id, CustomerId $customerId, Currency $currency = Currency::CZK): self
71	    {
72	        $order = new self($id, $customerId, $currency);
73	        $order->record(new OrderPlaced($id, $customerId, new \DateTimeImmutable()));
74	
75	        return $order;
76	    }
77	
78	    public function addItem(ProductId $productId, int $quantity, Money $unitPrice): void
79	    {
80	        if ($this->status !== OrderStatus::Draft) {
81	            throw InvalidOrderStateTransitionException::notAllowedInState('addItem', $this->status->value);
82	        }
83	
84	        $this->assertSameCurrency($unitPrice);
85	
86	        // Jedna položka na produkt: množství se sčítá, položka se neduplikuje.
87	        foreach ($this->lines as $existing) {
88	            if ($existing->productId->equals($productId)) {
89	                $existing->increaseQuantity($quantity);
90	                $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
91	
92	                return;
93	            }
94	        }
95	
96	        $this->lines->add(new OrderItem($this, $productId, $quantity, $unitPrice));
97	        $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
98	    }
99	
100	    public function applyDiscount(Money $discount): void
101	    {
102	        if ($this->status !== OrderStatus::Draft) {
103	            throw InvalidOrderStateTransitionException::notAllowedInState('applyDiscount', $this->status->value);
104	        }
105	
106	        $this->assertSameCurrency($discount);
107	        $this->discount = $discount;
108	    }
109	
110	    public function confirm(?\DateTimeImmutable $at = null): void
111	    {
112	        if (!$this->status->canTransitionTo(OrderStatus::Confirmed)) {
113	            throw InvalidOrderStateTransitionException::cannotTransition(
114	                $this->status->value,
115	                OrderStatus::Confirmed->value,
116	            );
117	        }
118	
119	        if ($this->lines->isEmpty()) {
120	            throw EmptyOrderException::cannotConfirm();
121	        }
122	
123	        $this->status = OrderStatus::Confirmed;
124	        $this->placedAt = $at ?? new \DateTimeImmutable();
125	        $this->record(new OrderConfirmed($this->id, $this->customerId, $this->placedAt));
126	    }
127	
128	    public function markPaid(): void
129	    {
130	        // Opakované doručení příkazu o platbě není chyba volajícího.
131	        if ($this->status === OrderStatus::Paid) {
132	            return;
133	        }
134	
135	        if (!$this->status->canTransitionTo(OrderStatus::Paid)) {
136	            throw InvalidOrderStateTransitionException::cannotTransition(
137	                $this->status->value,
138	                OrderStatus::Paid->value,
139	            );
140	        }
141	
142	        $this->status = OrderStatus::Paid;
143	        $this->record(new OrderPaid($this->id, new \DateTimeImmutable()));
144	    }
145	
146	    public function ship(): void
147	    {
148	        if ($this->status === OrderStatus::Shipped) {
149	            return;
150	        }
151	
152	        if (!$this->status->canTransitionTo(OrderStatus::Shipped)) {
153	            throw InvalidOrderStateTransitionException::cannotTransition(
154	                $this->status->value,
155	                OrderStatus::Shipped->value,
156	            );
157	        }
158	
159	        $this->status = OrderStatus::Shipped;
160	        $this->record(new OrderShipped($this->id, new \DateTimeImmutable()));
161	    }
162	
163	    public function deliver(): void
164	    {
165	        if (!$this->status->canTransitionTo(OrderStatus::Delivered)) {
166	            throw InvalidOrderStateTransitionException::cannotTransition(
167	                $this->status->value,
168	                OrderStatus::Delivered->value,
169	            );
170	        }
171	
172	        $this->status = OrderStatus::Delivered;
173	        $this->record(new OrderDelivered($this->id, new \DateTimeImmutable()));
174	    }
175	
176	    // Čas přichází zvenku, aby šel v testech zadat.
177	    public function cancel(string $reason, \DateTimeImmutable $when): void
178	    {
179	        // Opakované storno není chyba volajícího, jen už není co dělat.
180	        if ($this->status === OrderStatus::Cancelled) {
181	            return;
182	        }
183	
184	        // Storno je hrana grafu jako každá jiná: odeslanou ani doručenou
185	        // objednávku zpátky nevrátí.
186	        if (!$this->status->canTransitionTo(OrderStatus::Cancelled)) {
187	            throw InvalidOrderStateTransitionException::cannotTransition(
188	                $this->status->value,
189	                OrderStatus::Cancelled->value,
190	            );
191	        }
192	
193	        $this->status = OrderStatus::Cancelled;
194	        $this->record(new OrderCancelled($this->id, $this->customerId, $reason, $when));
195	    }
196	
197	    public function isOwnedBy(CustomerId $customerId): bool
198	    {
199	        return $this->customerId->equals($customerId);
200	    }
201	
202	    /** Součet položek před slevou. */
203	    public function totalAmount(): Money
204	    {
205	        $total = Money::zero($this->currency);
206	        foreach ($this->lines as $item) {
207	            $total = $total->add($item->subtotal());
208	        }
209	
210	        return $total;
211	    }
212	
213	    /** Částka, kterou zákazník platí: součet položek po slevě. */
214	    public function paidAmount(): Money
215	    {
216	        return $this->totalAmount()
217	            ->subtract($this->discount);
218	    }
219	
220	    private function assertSameCurrency(Money $amount): void
221	    {
222	        if ($amount->currency !== $this->currency) {
223	            throw CurrencyMismatchException::forOrder($this->currency, $amount->currency);
224	        }
225	    }
226	}
