64	    #[Route('/{id}/polozky', name: 'order_add_item', requirements: ['id' => Requirement::UUID], methods: ['POST'])]
65	    #[IsCsrfTokenValid('order_edit')]
66	    public function addItem(string $id, Request $request): Response
67	    {
68	        $order = $this->ownOrder($id);
69	        $product = $this->catalog->find(ProductId::fromString($request->getPayload()->getString('productId')))
70	            ?? throw $this->createNotFoundException('Product not found.');
71	
72	        $this->commandBus->dispatch(new AddOrderItem(
73	            $order->id,
74	            $product->id,
75	            max(1, $request->getPayload()->getInt('quantity', 1)),
76	            $product->price,
77	        ));
78	
79	        return $this->redirectToRoute('order_detail', ['id' => $order->id->value]);
80	    }
81	
82	    #[Route('/{id}/potvrdit', name: 'order_confirm', requirements: ['id' => Requirement::UUID], methods: ['POST'])]
83	    #[IsCsrfTokenValid('order_edit')]
84	    public function confirm(string $id): Response
85	    {
86	        $order = $this->ownOrder($id);
87	        $this->commandBus->dispatch(new ConfirmOrder($order->id));
88	
89	        return $this->redirectToRoute('order_detail', ['id' => $order->id->value]);
90	    }
91	
92	    #[Route('/{id}/zaplatit', name: 'order_pay', requirements: ['id' => Requirement::UUID], methods: ['POST'])]
93	    #[IsCsrfTokenValid('order_edit')]
94	    public function pay(string $id): Response
95	    {
96	        $order = $this->ownOrder($id);
97	        $this->commandBus->dispatch(new PayOrder($order->id));
98	
99	        return $this->redirectToRoute('order_detail', ['id' => $order->id->value]);
100	    }
101	
102	    /** Cizí objednávka se tváří jako neexistující (404, ne 403). */
103	    private function ownOrder(string $id): Order
104	    {
105	        $order = $this->orders->find(OrderId::fromString($id));
106	        if ($order === null || !$order->isOwnedBy($this->customerId())) {
107	            throw $this->createNotFoundException('Order not found.');
108	        }
109	
110	        return $order;
111	    }
112	
113	    private function customerId(): CustomerId
114	    {
115	        $user = $this->getUser();
116	        if (!$user instanceof SecurityUser) {
117	            throw $this->createAccessDeniedException();
118	        }
119	
120	        return $user->customerId();
121	    }
122	}
